using System.Globalization;
namespace BobbyBoi;
static class PixelText {
 static readonly Dictionary<char,byte[]> glyphs=("A:0E11111F111111 B:1E11111E11111E C:0F10101010100F D:1E11111111111E E:1F10101E10101F F:1F10101E101010 G:0F10101711110F H:1111111F111111 I:0E04040404040E J:0702020212120C K:11121418141211 L:1010101010101F M:111B1515111111 N:11191513111111 O:0E11111111110E P:1E11111E101010 Q:0E11111115120D R:1E11111E141211 S:0F10100E01011E T:1F040404040404 U:1111111111110E V:11111111110A04 W:11111115151B11 X:11110A040A1111 Y:11110A04040404 Z:1F01020408101F 0:0E11131519110E 1:040C040404040E 2:0E11010204081F 3:1E01010601011E 4:02060A121F0202 5:1F10101E01011E 6:0E10101E11110E 7:1F010204080808 8:0E11110E11110E 9:0E11110F01010E ?:0E110102040004 !:04040404040004 .:00000000000004 ,:00000000000408 -:0000001F000000 /:01010204081010 ':04040000000000 ::00040000040000 %:19190204081313 +:0004041F040400 =:00001F001F0000").Split(' ').ToDictionary(s=>s[0],s=>Enumerable.Range(0,7).Select(i=>byte.Parse(s.AsSpan(2+i*2,2),NumberStyles.HexNumber)).ToArray());
 public static void Draw(Graphics g,string text,int x,int y,Color color,int scale=2){using var brush=new SolidBrush(color);foreach(char raw in text){char c=char.ToUpperInvariant(raw);if(c!=' '){var rows=glyphs.TryGetValue(c,out var found)?found:glyphs['?'];for(int row=0;row<7;row++)for(int col=0;col<5;col++)if((rows[row]&(1<<(4-col)))!=0)g.FillRectangle(brush,x+col*scale,y+row*scale,scale,scale);}x+=6*scale;}}
 public static List<string> Wrap(string text,int columns){var lines=new List<string>();string current="";foreach(var word in text.Split(' ',StringSplitOptions.RemoveEmptyEntries)){foreach(var chunk in Enumerable.Range(0,(word.Length+columns-1)/columns).Select(i=>word.Substring(i*columns,Math.Min(columns,word.Length-i*columns)))){if(current.Length>0&&current.Length+chunk.Length+1>columns){lines.Add(current);current="";}current+=(current.Length>0?" ":"")+chunk;}}if(current.Length>0)lines.Add(current);return lines.Take(4).ToList();}
 public static void Panel(Graphics g,Rectangle r,Color accent){using var shadow=new SolidBrush(Color.FromArgb(130,0,0,0));g.FillRectangle(shadow,r.X+3,r.Y+4,r.Width,r.Height);using var outer=new SolidBrush(Color.FromArgb(19,12,25));g.FillRectangle(outer,r);using var trim=new SolidBrush(accent);g.FillRectangle(trim,r.X+2,r.Y+2,r.Width-4,r.Height-4);using var inner=new SolidBrush(Color.FromArgb(39,30,45));g.FillRectangle(inner,r.X+4,r.Y+4,r.Width-8,r.Height-8);using var shine=new SolidBrush(Color.FromArgb(90,accent));g.FillRectangle(shine,r.X+5,r.Y+5,r.Width-10,2);}
}
sealed class MinecraftBubble:IDisposable {
 Bitmap? image;string key="";
 public void Draw(Graphics g,string text,float age,int width,Color accent){var lines=PixelText.Wrap(text,18);int shown=Math.Clamp((int)(age*52)+1,0,lines.Sum(s=>s.Length));string next=text+"/"+shown+"/"+accent.ToArgb();if(next!=key){key=next;image?.Dispose();int w=Math.Clamp(lines.Select(s=>s.Length*12+20).DefaultIfEmpty(100).Max(),112,236),h=29+lines.Count*18;image=new Bitmap(w+5,h+14);using var canvas=Graphics.FromImage(image);PixelText.Panel(canvas,new(0,0,w,h),accent);PixelText.Draw(canvas,"BOBBYBOI",11,9,accent,1);int remain=shown;for(int i=0;i<lines.Count;i++){string part=lines[i][..Math.Min(lines[i].Length,remain)];remain=Math.Max(0,remain-part.Length);PixelText.Draw(canvas,part,12,23+i*18,Color.Black);PixelText.Draw(canvas,part,10,21+i*18,Color.FromArgb(243,235,216));}using var border=new SolidBrush(Color.FromArgb(19,12,25));using var fill=new SolidBrush(accent);canvas.FillRectangle(border,w/2-7,h-1,14,5);canvas.FillRectangle(border,w/2-4,h+4,8,4);canvas.FillRectangle(fill,w/2-4,h-1,8,4);canvas.FillRectangle(fill,w/2-2,h+3,4,3);}g.DrawImageUnscaled(image!,(width-image!.Width)/2,7);}
 public void Dispose()=>image?.Dispose();
}
